// macOS replacement for dll_resources.cpp: resources are compiled into the dylib (see gen_resources.py).
#include "dll_resources.hpp"
#include "embedded_resources.inc"

reshade::resources::data_resource reshade::resources::load_data_resource(unsigned short id)
{
	for (const embedded_res &r : kEmbedded)
		if (r.id == id) return { r.size, r.data };
	return { 0, nullptr }; // e.g. precompiled DirectX shaders, which do not exist on macOS
}

#if RESHADE_LOCALIZATION
// ---- localization: string tables of the 16 languages ReShade ships (generated by gen_strings.py) ----
#include "localization_data.inc"
#include <map>
#include <set>
#include <unordered_map>
#import <Foundation/Foundation.h>

namespace
{
	using Table = std::unordered_map<unsigned short, const char *>;
	const std::map<std::string, Table> &tables()
	{
		static const std::map<std::string, Table> all = [] {
			std::map<std::string, Table> t;
			for (const LocalizedString &s : kStrings) t[s.language][s.id] = s.text;
			return t;
		}();
		return all;
	}

	/// The user's preferred macOS language, mapped to one of the shipped languages ("de-DE" for "de", "de-AT", ...), else English.
	std::string system_language()
	{
		static const std::string language = [] {
			@autoreleasepool
			{
				for (NSString *preferred in [NSLocale preferredLanguages])
				{
					std::string code = preferred.UTF8String;
					for (char &c : code) if (c == '_') c = '-';
					const auto &all = tables();
					if (all.count(code)) return code;
					const std::string primary = code.substr(0, 2);
					// Chinese: Traditional scripts map to zh-HK, everything else to zh-CN
					if (primary == "zh") return std::string(code.find("Hant") != std::string::npos || code.find("HK") != std::string::npos || code.find("TW") != std::string::npos ? "zh-HK" : "zh-CN");
					for (const auto &entry : all) if (entry.first.compare(0, 2, primary) == 0) return entry.first;
				}
			}
			return std::string("en-US");
		}();
		return language;
	}

	thread_local std::string t_language; // empty = system language
}

std::string reshade::resources::load_string(unsigned short id)
{
	const auto &all = tables();
	const std::string language = t_language.empty() ? system_language() : t_language;
	for (const std::string &candidate : { language, std::string("en-US") })
		if (const auto table = all.find(candidate); table != all.end())
			if (const auto text = table->second.find(id); text != table->second.end())
				return text->second;
	return std::string();
}

std::string reshade::resources::get_current_language() { return t_language.empty() ? system_language() : t_language; }

std::string reshade::resources::set_current_language(const std::string &language)
{
	std::string previous = t_language.empty() ? system_language() : t_language;
	t_language = language;
	return previous;
}

std::vector<std::string> reshade::resources::get_languages()
{
	std::vector<std::string> languages;
	for (const auto &entry : tables()) languages.push_back(entry.first);
	return languages;
}
#endif
